let forceTimer;
let groupPoll;
let childResult;
let outputViolation;
const MAX_STREAM_BYTES = 8 * 1024 * 1024;
const MAX_LINE_BYTES = 1024 * 1024;
const outputState = {
  stdout: { bytes: 0, lineBytes: 0 },
  stderr: { bytes: 0, lineBytes: 0 },
};

function groupExists() {
  try {
    process.kill(-child.pid, 0);
    return true;
  } catch {
    return false;
  }
}

function exitFromChild() {
  if (!childResult) return;
  clearInterval(watchdog);
  if (forceTimer) clearTimeout(forceTimer);
  if (groupPoll) clearInterval(groupPoll);
  process.exit(outputViolation ? 1 : childResult.signal ? 1 : childResult.code ?? 1);
}

function finishWhenGroupIsGone() {
  if (!childResult) return;
  if (!groupExists()) {
    exitFromChild();
    return;
  }
  if (!groupPoll) {
    groupPoll = setInterval(() => {
      if (!groupExists()) exitFromChild();
    }, 50);
  }
}

function stopGroup() {
  if (stopping) return;
  stopping = true;
  try { process.kill(-child.pid, "SIGTERM"); } catch {}
  forceTimer = setTimeout(() => {
    try { process.kill(-child.pid, "SIGKILL"); } catch {}
  }, 2_000);
  finishWhenGroupIsGone();
}

